"""`gw status` → STATUS.md (spec §13) and `gw start` → terminal briefing (spec §13.5).

Both reuse site.extract so classification rules (§12) apply identically.
"""

from __future__ import annotations

import datetime as dt
import re
from pathlib import Path
from typing import Any

from .project import load_config
from .site import LABELS, STATUS_ORDER, extract

EMOJI = {"human-verified": "🟢", "auto-checked": "🔵", "unverified": "🟡", "disputed": "🔴", "retracted": "⚪"}
ORAL = "🟠"
BLANK = "_(blank)_"

T = {
    "en": {
        "title": "Project status", "auto": "Auto-generated by Groundwork from this repository's record. Do not edit by hand.",
        "stage": "Stage", "updated": "Generated", "commit": "Commit", "goal": "Goal", "state": "Current state",
        "pending": "Waiting for a decision", "approve_hint": "Approve by reviewing the pull request that adds it.",
        "verif": "Verification", "of": "of", "items": "items", "human": "human-verified",
        "questions": "Open questions", "decisions": "Recent decisions (T2/T3)", "latest": "Latest session",
        "blocked": "Blocked", "next": "Next", "none": "None.", "hidden": "item(s) withheld (restricted).",
        "unreadable": "record(s) could not be read; run `gw check`:", "legend": "Legend",
        "proposed_by": "proposed by", "ask": "ask", "by": "by", "approved": "approved by",
    },
    "zh": {
        "title": "项目状态", "auto": "本页由 Groundwork 根据仓库记录自动生成，请勿手动修改。",
        "stage": "阶段", "updated": "生成时间", "commit": "版本", "goal": "目标", "state": "当前状态",
        "pending": "待决定事项", "approve_hint": "在对应的 Pull Request 中审批即可生效。",
        "verif": "核验状态", "of": "/", "items": "条", "human": "已人工核验",
        "questions": "待解答问题", "decisions": "近期决策（T2/T3）", "latest": "最近一次工作记录",
        "blocked": "卡点", "next": "下一步", "none": "暂无。", "hidden": "条内容因保密等级未显示。",
        "unreadable": "条记录格式有误，请运行 `gw check`：", "legend": "标识说明",
        "proposed_by": "提议人", "ask": "请问", "by": "决定人", "approved": "批准人",
    },
}


def _lang(root: Path, lang: str | None) -> str:
    lang = lang or str(load_config(root).get("language") or "en")
    return lang if lang in T else "en"


def _clean(text: str | None) -> str:
    t = re.sub(r"<!--.*?-->", "", text or "", flags=re.DOTALL).strip()
    return "" if not t or t == BLANK else t


def render_status(root: Path, lang: str | None = None, now: dt.datetime | None = None) -> str:
    lang = _lang(root, lang)
    t, L = T[lang], LABELS[lang]
    d = extract(root, "advisor", now=now)
    m, pf, ps = d["meta"], d["project"]["fm"], d["project"]["sections"]
    out: list[str] = [f"# {t['title']}: {pf.get('title') or ''}".rstrip(": "), ""]
    out.append(f"> {t['auto']}  ")
    out.append(f"> {t['stage']}: **{pf.get('stage', '?')}** · {t['updated']}: {m['generated_at'].replace('T', ' ')}"
               f" · {t['commit']}: `{(m['commit'] or 'n/a')[:8]}`")
    out.append("")
    if m["unreadable"]:
        out += [f"> ⚠️ {len(m['unreadable'])} {t['unreadable']} " + ", ".join(m["unreadable"]), ""]
    if m["hidden_items"]:
        out += [f"> 🔒 {m['hidden_items']} {t['hidden']}", ""]

    if _clean(ps.get("Goal")):
        out += [f"## {t['goal']}", "", _clean(ps.get("Goal")), ""]
    if _clean(ps.get("Current state")):
        out += [f"## {t['state']}", "", _clean(ps.get("Current state")), ""]

    out += [f"## {t['pending']} ({len(d['pending_decisions'])})", ""]
    if d["pending_decisions"]:
        for x in d["pending_decisions"]:
            f = x["fm"]
            out.append(f"- **{f.get('tier')}** {f.get('title')} · #{f.get('id')} · {t['proposed_by']} "
                       f"{f.get('proposed_by') or f.get('decider') or '?'} · `decisions/{x['file']}`")
        out += ["", f"_{t['approve_hint']}_", ""]
    else:
        out += [t["none"], ""]

    v = d["verification"]
    out += [f"## {t['verif']}", ""]
    out.append(f"**{v['counts']['human-verified']}** {t['of']} {v['total']} {t['items']} {t['human']}")
    out.append("")
    parts = [f"{EMOJI[s]} {L['status'][s]} {v['counts'][s]}" for s in STATUS_ORDER if v["counts"][s]]
    if v["oral_only"]:
        parts.append(f"{ORAL} {L['oral_only']} {v['oral_only']}")
    out += [" · ".join(parts) if parts else t["none"], ""]

    out += [f"## {t['questions']} ({len(d['questions'])})", ""]
    out += [f"- {q.get('question')} · {q.get('id')} · {t['ask']} @{_gh(d, q.get('routed_to'))}"
            for q in d["questions"]] or [t["none"]]
    out.append("")

    big = [x for x in d["decisions"] if x["fm"].get("tier") in ("T2", "T3") and x["fm"].get("status") != "proposed"][:5]
    out += [f"## {t['decisions']}", ""]
    for x in big:
        f = x["fm"]
        tail = f" · {t['approved']} {f['approved_by']}" if f.get("approved_by") else ""
        out.append(f"- **{f.get('tier')}** {L['dstatus'].get(f.get('status'), f.get('status'))} · {f.get('title')}"
                   f" · #{f.get('id')} · {f.get('date')} · {t['by']} {f.get('decider')}{tail}")
    if not big:
        out.append(t["none"])
    out.append("")

    confirmed = [s for s in d["sessions"] if s["fm"].get("confirmed_by")]
    if confirmed:
        s = confirmed[0]
        out += [f"## {t['latest']}: {s['fm'].get('date')} · {s['fm'].get('principal')}", ""]
        for key, lab in (("Blocked", t["blocked"]), ("Next", t["next"])):
            if _clean(s["sections"].get(key)):
                out += [f"**{lab}:** {_clean(s['sections'].get(key))}", ""]

    legend = " · ".join(f"{EMOJI[s]} {L['status'][s]}" for s in STATUS_ORDER) + f" · {ORAL} {L['oral_only']}"
    out += ["---", "", f"<sub>{t['legend']}: {legend}</sub>  ",
            f"<sub>{m['tool']} · spec v{m['spec']}</sub>", ""]
    return "\n".join(out)


def _gh(d: dict[str, Any], pid: Any) -> str:
    p = d["principals"].get(str(pid)) or {}
    return str(p.get("github") or pid)


def write_status(root: Path, lang: str | None = None, now: dt.datetime | None = None) -> Path:
    path = root / "STATUS.md"
    path.write_text(render_status(root, lang, now), encoding="utf-8")
    return path


def briefing(root: Path, who: str, now: dt.datetime | None = None) -> str:
    """Plain-text start-of-work briefing for a human or an agent (spec §5.1, §13.5)."""
    d = extract(root, "receiver", now=now)
    pf = d["project"]["fm"]
    lines = [f"Project: {pf.get('title', '?')}  (stage: {pf.get('stage', '?')})"]
    confirmed = [s for s in d["sessions"] if s["fm"].get("confirmed_by")]
    drafts = [s for s in d["sessions"] if not s["fm"].get("confirmed_by")]
    if confirmed:
        s = confirmed[0]
        lines.append(f"\nLast session: {s['fm'].get('date')} by {s['fm'].get('principal')}")
        for key in ("Did", "Thinking", "Blocked", "Next", "Unverified items touched"):
            val = _clean(s["sections"].get(key))
            if val:
                lines.append(f"  {key}: {' '.join(val.split())}")
    else:
        lines.append("\nNo confirmed session yet. Run `gw end` when you finish working.")
    if drafts:
        lines.append(f"\n⚠ {len(drafts)} unconfirmed session draft(s): " + ", ".join(s["file"] for s in drafts))
    if d["pending_decisions"]:
        lines.append("\nWaiting for a decision:")
        lines += [f"  #{x['fm'].get('id')} [{x['fm'].get('tier')}] {x['fm'].get('title')}" for x in d["pending_decisions"]]
    mine = [q for q in d["questions"] if str(q.get("routed_to")) == who]
    if mine:
        lines.append(f"\nQuestions for you ({who}):")
        lines += [f"  {q.get('id')}: {q.get('question')}" for q in mine]
    v = d["verification"]
    if v["total"]:
        lines.append(f"\nVerification: {v['counts']['human-verified']}/{v['total']} human-verified, "
                     f"{v['counts']['unverified']} unverified, {v['counts']['disputed']} disputed, "
                     f"{v['oral_only']} oral-only")
    if d["meta"]["unreadable"]:
        lines.append("\n⚠ Unreadable records (run `gw check`): " + ", ".join(d["meta"]["unreadable"]))
    return "\n".join(lines)
